import os
import urllib.request
import re

os.makedirs('assets', exist_ok=True)

def write_icon_set(name, inner_dark, inner_light=None, inner_auto=None):
    if inner_light is None:
        inner_light = inner_dark
    if inner_auto is None:
        inner_auto = inner_dark
    
    # 1. auto
    auto_svg = f'''<svg id="{name}" xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256">
  <style>
    #{name} .{name}-bg {{ fill: #242938; }}
    @media (prefers-color-scheme: light) {{
      #{name} .{name}-bg {{ fill: #F4F2ED; }}
    }}
  </style>
  <rect class="{name}-bg" width="256" height="256" rx="60" fill="#242938"/>
  {inner_auto}
</svg>'''
    with open(f'assets/{name}-auto.svg', 'w') as f:
        f.write(auto_svg)

    # 2. dark
    dark_svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256">
  <rect width="256" height="256" rx="60" fill="#242938"/>
  {inner_dark}
</svg>'''
    with open(f'assets/{name}-dark.svg', 'w') as f:
        f.write(dark_svg)

    # 3. light
    light_svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256">
  <rect width="256" height="256" rx="60" fill="#F4F2ED"/>
  {inner_light}
</svg>'''
    with open(f'assets/{name}-light.svg', 'w') as f:
        f.write(light_svg)

    # 4. base .svg (for unthemed fallback)
    with open(f'assets/{name}.svg', 'w') as f:
        f.write(auto_svg)
    print(f'Wrote icon set for {name}')

